(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  if (!inputPath) throw new Error('INPUT_PATH env var required');
  if (!existsSync(inputPath)) throw new Error(`Input file not found: ${inputPath}`);
  const content = readFileSync(inputPath, 'utf8');
  globalThis.xmlContent = content;
})();

(async () => {
  const jspMod = await import('jsparsers');
  const jsp = jspMod.default || jspMod;
  const xmlParser = jsp.xml();
  if (typeof xmlParser.load === 'function') {
    xmlParser.load(globalThis.xmlContent);
  } else if (typeof xmlParser.parse === 'function') {
    xmlParser.parse(globalThis.xmlContent);
  }
  const tomlStr = typeof xmlParser.toml === 'function' ? xmlParser.toml() : xmlParser.toml;
  globalThis.tomlStr = tomlStr;
})();
